import sys
from typing import List

def max_final_element(N: int, A: List[int]) -> None:
    dp = [[0] * N for _ in range(N)]
    parent = [[None] * N for _ in range(N)]

    for length in range(1, N + 1):
        for i in range(N - length + 1):
            j = i + length - 1
            if length == 1:
                dp[i][j] = A[i]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
                if dp[i + 1][j] > dp[i][j - 1]:
                    parent[i][j] = 'left'
                else:
                    parent[i][j] = 'right'

    def reconstruct_path(i: int, j: int) -> List[int]:
        path = []
        while i <= j:
            if parent[i][j] == 'left':
                path.append(i)
                i += 1
            else:
                path.append(j)
                j -= 1
        return path[::-1]

    result = dp[0][N - 1]
    path = reconstruct_path(0, N - 1)

    print(result)
    print(len(path))
    for p in path:
        print(p + 1)

