    parent = [[-1] * N for _ in range(N)]

    for length in range(2, N + 1):
        for start in range(N - length + 1):
            end = start + length - 1
            for mid in range(start, end):
                if dp[start][mid] + dp[mid + 1][end] > dp[start][end]:
                    dp[start][end] = dp[start][mid] + dp[mid + 1][end]
                    parent[start][end] = mid

    def reconstruct_path(start: int, end: int) -> List[int]:
        if start == end:
            return [start]
        mid = parent[start][end]
        if mid == -1:
            return [start, end]
        return reconstruct_path(start, mid) + reconstruct_path(mid + 1, end)

    result = dp[0][N - 1]
    path = reconstruct_path(0, N - 1)
    path = [x + 1 for x in path]

    print(result)
